INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7678387, 1255871, 129512, '<td valign="top">Wonderful Colors<br/>7</td>', 'Wonderful Colors7', '2020-11-01 00:07:07.000000', NULL, 1),
(7678391, 1255832, 101668, '<td valign="top">Love this</td>', 'Love this', '2020-11-01 04:42:18.000000', NULL, 1),
(7678423, 1255765, 65234, '<td valign="top">Great POV.</td>', 'Great POV.', '2020-11-01 10:57:45.000000', NULL, 1),
(7678424, 1255597, 65234, '<td valign="top">Nice still life.</td>', 'Nice still life.', '2020-11-01 11:00:12.000000', NULL, 1),
(7678425, 1255816, 65234, '<td valign="top">The one that got away...</td>', 'The one that got away...', '2020-11-01 11:42:08.000000', NULL, 1),
(7678426, 1255800, 65234, '<td valign="top">Airborne! Great capture; love the tongue.</td>', 'Airborne! Great capture; love the tongue.', '2020-11-01 11:44:29.000000', NULL, 1),
(7678427, 1254931, 65234, '<td valign="top">Phenomenal detail and DOF. The diagonal to the composition with the positioning of the ants is very pleasing to the eye. Nice of them to pose for you :-) Best image in the challenge, IMO.</td>', 'Phenomenal detail and DOF. The diagonal to the composition with the positioning of the ants is very pleasing to the eye. Nice of them to pose for you :-) Best image in the challenge, IMO.', '2020-11-01 11:46:39.000000', NULL, 1),
(7678428, 1255142, 65234, '<td valign="top">Very well done.</td>', 'Very well done.', '2020-11-01 11:46:59.000000', NULL, 1),
(7678429, 1255846, 65234, '<td valign="top">Love that the male is bellowing. Claiming his harem, in case other males were getting any ideas. Fun capture.</td>', 'Love that the male is bellowing. Claiming his harem, in case other males were getting any ideas. Fun capture.', '2020-11-01 11:47:55.000000', NULL, 1),
(7678430, 1255814, 65234, '<td valign="top">Someone is in BIG trouble. I notice the one being screamed at is not making eye contact with the screamer LOL.</td>', 'Someone is in BIG trouble. I notice the one being screamed at is not making eye contact with the screamer LOL.', '2020-11-01 11:48:43.000000', NULL, 1),
(7678431, 1255804, 65234, '<td valign="top">Beautiful kitten; nice detail and DOF.</td>', 'Beautiful kitten; nice detail and DOF.', '2020-11-01 11:49:04.000000', NULL, 1),
(7678432, 1255821, 65234, '<td valign="top">Interesting feathers, especially the mop on top of his/her head.</td>', 'Interesting feathers, especially the mop on top of his/her head.', '2020-11-01 11:49:46.000000', NULL, 1),
(7678433, 1255832, 65234, '<td valign="top">Uh-oh. I don''t think I''d like to be the subject of their curiosity. Those are some BIG birds and the leader of the gang looks angry.</td>', 'Uh-oh. I don''t think I''d like to be the subject of their curiosity. Those are some BIG birds and the leader of the gang looks angry.', '2020-11-01 11:51:40.000000', NULL, 1),
(7678434, 1255831, 65234, '<td valign="top">Love that sky, with the clouds leading the eye to the building.</td>', 'Love that sky, with the clouds leading the eye to the building.', '2020-11-01 11:52:33.000000', NULL, 1),
(7678435, 1255847, 65234, '<td valign="top">Nice light and detail.</td>', 'Nice light and detail.', '2020-11-01 11:52:47.000000', NULL, 1),
(7678436, 1254967, 65234, '<td valign="top">Looks like one of them pooped on the poor horse! very inconsiderate.</td>', 'Looks like one of them pooped on the poor horse! very inconsiderate.', '2020-11-01 11:53:25.000000', NULL, 1),
(7678437, 1255810, 65234, '<td valign="top">Affected by the fires? Makes this just a beautiful memory :-(</td>', 'Affected by the fires? Makes this just a beautiful memory :-(', '2020-11-01 11:55:03.000000', NULL, 1),
(7678438, 1255753, 65234, '<td valign="top">Gorgeous foliage.</td>', 'Gorgeous foliage.', '2020-11-01 11:55:17.000000', NULL, 1),
(7678439, 1255757, 65234, '<td valign="top">Love your timing with the person in the midst of running through the rain.</td>', 'Love your timing with the person in the midst of running through the rain.', '2020-11-01 11:56:06.000000', NULL, 1),
(7678453, 1255852, 86447, '<td valign="top">Deigo is beautiful.  But, the eyes are too overcooked for my taste.  LOVE the BW!!  7</td>', 'Deigo is beautiful.  But, the eyes are too overcooked for my taste.  LOVE the BW!!  7', '2020-11-01 14:19:42.000000', NULL, 1),
(7678454, 1255790, 30049, '<td valign="top">Hooray!  A drone shot I can appreciate and like.  :-)  Nice.</td>', 'Hooray!  A drone shot I can appreciate and like.  :-)  Nice.', '2020-11-01 15:27:14.000000', NULL, 1),
(7678455, 1255777, 30049, '<td valign="top">There''s that windshield look again.  :-)  Well, not quite so defined this time.  Pretty view.</td>', 'There''s that windshield look again.  :-)  Well, not quite so defined this time.  Pretty view.', '2020-11-01 15:28:28.000000', NULL, 1),
(7678456, 1255625, 30049, '<td valign="top">Awesome capture!  Wish it wasn''t a square crop, but still, very nice.</td>', 'Awesome capture!  Wish it wasn''t a square crop, but still, very nice.', '2020-11-01 15:30:52.000000', NULL, 1),
(7678461, 1255810, 30049, '<td valign="top">Hmm.  Feels like we''ve seen this before.  ???  Lovely location and well captured.<br/> <br/>Ah, found it.  <a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1248636" rel="nofollow" target="_blank"><img border="0" src="//images.dpchallenge.com/images_challenge/3000-3999/3024/120/Copyrighted_Image_Reuse_Prohibited_1248636.jpg" xalt="'' . substr(''//images.dpchallenge.com/images_challenge/3000-3999/3024/120/Copyrighted_Image_Reuse_Prohibited_1248636.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/3000-3999/3024/120/Copyrighted_Image_Reuse_Prohibited_1248636.jpg'', ''/'') + 1) . ''"/></a>  Lighting is a bit different.  Haven''t seen you around since April?!  Yikes.  Well, good luck with this one.  Should do well.</td>', 'Hmm.  Feels like we''ve seen this before.  ???  Lovely location and well captured. Ah, found it.    Lighting is a bit different.  Haven''t seen you around since April?!  Yikes.  Well, good luck with this one.  Should do well.', '2020-11-01 15:43:06.000000', NULL, 1),
(7678462, 1255832, 30049, '<td valign="top">Not these guys again?  LOL  Interesting (curious) creatures for sure.  Good luck, hope it does well for you Fred.</td>', 'Not these guys again?  LOL  Interesting (curious) creatures for sure.  Good luck, hope it does well for you Fred.', '2020-11-01 15:46:54.000000', NULL, 1),
(7678463, 1255808, 30049, '<td valign="top">Beautiful!  Lovely wildlife capture.</td>', 'Beautiful!  Lovely wildlife capture.', '2020-11-01 15:52:46.000000', NULL, 1),
(7678464, 1255765, 30049, '<td valign="top">Could have called this one "just down the river".  :-)  Good luck with this aerial view there Girish.  I''ll bet this looks a whole lot different once the leaves come off, eh?</td>', 'Could have called this one "just down the river".  :-)  Good luck with this aerial view there Girish.  I''ll bet this looks a whole lot different once the leaves come off, eh?', '2020-11-01 15:56:55.000000', NULL, 1),
(7678465, 1255826, 30049, '<td valign="top">Love the structure of this tree.  Simple, yet pleasant image.  Good luck.</td>', 'Love the structure of this tree.  Simple, yet pleasant image.  Good luck.', '2020-11-01 15:57:24.000000', NULL, 1),
(7678466, 1255656, 30049, '<td valign="top">Ah man.  There must be a pretty good story here.  Guy looks like a character.  Check out those pants!  Nice B&amp;W treatment.  Nice capture. Good luck.</td>', 'Ah man.  There must be a pretty good story here.  Guy looks like a character.  Check out those pants!  Nice B&W treatment.  Nice capture. Good luck.', '2020-11-01 15:59:19.000000', NULL, 1),
(7678467, 1255852, 30049, '<td valign="top">A portrait worthy of printing.  Nicely done.</td>', 'A portrait worthy of printing.  Nicely done.', '2020-11-01 16:00:12.000000', NULL, 1),
(7678468, 1255610, 30049, '<td valign="top">I really like the blue light from the tower in the background.  Nice complement to the orange light in the foreground.  Would be nice to have a person or two in here for some subject interest.  Good luck Georges.</td>', 'I really like the blue light from the tower in the background.  Nice complement to the orange light in the foreground.  Would be nice to have a person or two in here for some subject interest.  Good luck Georges.', '2020-11-01 16:03:36.000000', NULL, 1),
(7678469, 1255880, 30049, '<td valign="top">It''s a fair study on fall leaves.  A little ho-hummish.  Sorry, just first impression.  Good luck (Renee?)</td>', 'It''s a fair study on fall leaves.  A little ho-hummish.  Sorry, just first impression.  Good luck (Renee?)', '2020-11-01 16:06:13.000000', NULL, 1),
(7678470, 1255675, 30049, '<td valign="top">I like this.  I would like it a lot more, I think, if the man and main window filled the frame substantially more.</td>', 'I like this.  I would like it a lot more, I think, if the man and main window filled the frame substantially more.', '2020-11-01 16:07:13.000000', NULL, 1),
(7678471, 1255876, 30049, '<td valign="top">Yes, it''s a moment.  Just passing on by.</td>', 'Yes, it''s a moment.  Just passing on by.', '2020-11-01 16:09:09.000000', NULL, 1),
(7678472, 1255879, 30049, '<td valign="top">Cute.  :-)</td>', 'Cute.  :-)', '2020-11-01 16:09:25.000000', NULL, 1),
(7678473, 1255814, 30049, '<td valign="top">:-)  Perfect title.</td>', ':-)  Perfect title.', '2020-11-01 16:15:15.000000', NULL, 1),
(7678474, 1255778, 30049, '<td valign="top">Nice.  Like the inclusion of three blossoms and the processing is very pleasing.</td>', 'Nice.  Like the inclusion of three blossoms and the processing is very pleasing.', '2020-11-01 16:18:40.000000', NULL, 1),
(7678475, 1254967, 30049, '<td valign="top">I get the hanging on for a ride, but come on, do they really have to use the bathroom there too!  Nicely captured image.  Good luck.</td>', 'I get the hanging on for a ride, but come on, do they really have to use the bathroom there too!  Nicely captured image.  Good luck.', '2020-11-01 16:19:38.000000', NULL, 1),
(7678477, 1255824, 30049, '<td valign="top">I know it''s a long exposure, and certainly on purpose, but I really don''t like the way the water looks in this at all.  Almost looks like a slice of border added ready for a text line to fill in.  Otherwise it''s a wonderful capture of the mountains.</td>', 'I know it''s a long exposure, and certainly on purpose, but I really don''t like the way the water looks in this at all.  Almost looks like a slice of border added ready for a text line to fill in.  Otherwise it''s a wonderful capture of the mountains.', '2020-11-01 16:23:46.000000', NULL, 1),
(7678478, 1255600, 156466, '<td valign="top">So little in sharp focus here.</td>', 'So little in sharp focus here.', '2020-11-01 16:24:06.000000', NULL, 1),
(7678479, 1255790, 156466, '<td valign="top">I love the abstract nature of this, it just feels over processed from a texture/sharpness perspective.</td>', 'I love the abstract nature of this, it just feels over processed from a texture/sharpness perspective.', '2020-11-01 16:25:30.000000', NULL, 1),
(7678480, 1255832, 156466, '<td valign="top">Could have benefited from a crop that eliminated those power lines. You don''t need the room at the top. I may not do well here, but you''ve got a great image in there.</td>', 'Could have benefited from a crop that eliminated those power lines. You don''t need the room at the top. I may not do well here, but you''ve got a great image in there.', '2020-11-01 16:26:47.000000', NULL, 1),
(7678481, 1255142, 156466, '<td valign="top">Well, Mark, this should almost sew up another FS crown for you. Well done.</td>', 'Well, Mark, this should almost sew up another FS crown for you. Well done.', '2020-11-01 16:27:29.000000', NULL, 1),
(7678482, 1255333, 156466, '<td valign="top">I get what you''re trying to do with the mountain symmetry in the background, but I think the winner here demands you crop in instead of pulling eyes down to the bottom 10th of the image.</td>', 'I get what you''re trying to do with the mountain symmetry in the background, but I think the winner here demands you crop in instead of pulling eyes down to the bottom 10th of the image.', '2020-11-01 16:28:55.000000', NULL, 1),
(7678483, 1255625, 156466, '<td valign="top">I love everything but the road running out of the frame before it (sort of) turns back in. Given the square crop I don''t know what you started with, but the processing is wonderful. I just might have sacrificed a bit of the sky and pulled up from the bottom a bit. Really good. Could have been a ribbon for me.</td>', 'I love everything but the road running out of the frame before it (sort of) turns back in. Given the square crop I don''t know what you started with, but the processing is wonderful. I just might have sacrificed a bit of the sky and pulled up from the bottom a bit. Really good. Could have been a ribbon for me.', '2020-11-01 16:34:22.000000', NULL, 1),
(7678484, 1255820, 156466, '<td valign="top">I hate still life, in general, but this is really well processed ... except the textures. I could live without them.</td>', 'I hate still life, in general, but this is really well processed ... except the textures. I could live without them.', '2020-11-01 16:36:14.000000', NULL, 1),
(7678485, 1254967, 156466, '<td valign="top">I get why you wanted to show the whole horse, but it turns a photo into a snapshot. There''s a really good photo if you crop in.</td>', 'I get why you wanted to show the whole horse, but it turns a photo into a snapshot. There''s a really good photo if you crop in.', '2020-11-01 16:37:21.000000', NULL, 1),
(7678486, 1255496, 156466, '<td valign="top">No idea what you started with, but the shadowed areas are still too shadowed for me. You''ve got a lot of frame taken up, show us what''s there.</td>', 'No idea what you started with, but the shadowed areas are still too shadowed for me. You''ve got a lot of frame taken up, show us what''s there.', '2020-11-01 16:39:56.000000', NULL, 1),
(7678487, 1255298, 114285, '<td valign="top">What a wonderful crisp photo, probably the blue.</td>', 'What a wonderful crisp photo, probably the blue.', '2020-11-01 18:49:53.000000', NULL, 1),
(7678569, 1255733, 156466, '<td valign="top">I really like this, but what''s keeping me from loving it is what is and what is not in focus. Your focal plane is so narrow that you have the center of the bags in focus but most of what you''re showing us isn''t. I would have preferred the leading edge of the bag be in focus and it''s not (I even put my old man peepers on to make sure). Would have been near the top for me otherwise.</td>', 'I really like this, but what''s keeping me from loving it is what is and what is not in focus. Your focal plane is so narrow that you have the center of the bags in focus but most of what you''re showing us isn''t. I would have preferred the leading edge of the bag be in focus and it''s not (I even put my old man peepers on to make sure). Would have been near the top for me otherwise.', '2020-11-02 11:01:09.000000', NULL, 1),
(7678607, 1255553, 259105, '<td valign="top">I love this photo, its just the bottom half of the bird is out of focus, but other than that great shot</td>', 'I love this photo, its just the bottom half of the bird is out of focus, but other than that great shot', '2020-11-02 19:21:39.000000', NULL, 1),
(7678625, 1255790, 4008, '<td valign="top">A pity the birds are nowhere to be seen, would be so much more interesting with them in it.</td>', 'A pity the birds are nowhere to be seen, would be so much more interesting with them in it.', '2020-11-03 08:33:55.000000', NULL, 1),
(7678626, 1255839, 4008, '<td valign="top">Beautiful soft image, maybe a bit dark in the shadows. I would try to increase exposure or use fill light in post processing to see if it would add some more glow and depth in the foreground.</td>', 'Beautiful soft image, maybe a bit dark in the shadows. I would try to increase exposure or use fill light in post processing to see if it would add some more glow and depth in the foreground.', '2020-11-03 08:41:36.000000', NULL, 1),
(7678627, 1255597, 4008, '<td valign="top">very nice balanced still life.</td>', 'very nice balanced still life.', '2020-11-03 08:42:56.000000', NULL, 1),
(7678628, 1255808, 4008, '<td valign="top">great sharpness on the animal, good DOF</td>', 'great sharpness on the animal, good DOF', '2020-11-03 08:44:14.000000', NULL, 1),
(7678629, 1255810, 4008, '<td valign="top">Nice layered image. I would suggest to also try to convert to black and white.</td>', 'Nice layered image. I would suggest to also try to convert to black and white.', '2020-11-03 08:47:27.000000', NULL, 1),
(7678630, 1255876, 4008, '<td valign="top">the horizon .....tilted</td>', 'the horizon .....tilted', '2020-11-03 08:48:07.000000', NULL, 1),
(7678631, 1255600, 4008, '<td valign="top">Not a very interesting composition. Also the piece of paper is distracting.</td>', 'Not a very interesting composition. Also the piece of paper is distracting.', '2020-11-03 08:49:44.000000', NULL, 1),
(7678632, 1255577, 4008, '<td valign="top">Nice soft portrait. Maybe better if you all would have worn white?</td>', 'Nice soft portrait. Maybe better if you all would have worn white?', '2020-11-03 08:51:23.000000', NULL, 1),
(7678634, 1255816, 4008, '<td valign="top">Great action shot. I like how the fish is escaping to the left. The fact that this results in a strange composition emphasises the lucky escape.</td>', 'Great action shot. I like how the fish is escaping to the left. The fact that this results in a strange composition emphasises the lucky escape.', '2020-11-03 08:53:15.000000', NULL, 1),
(7678637, 1255625, 4008, '<td valign="top">Great B&amp;W tones and great landscape. But it almost feels like two separate images, one the road with trees below and the other the trees, mountain and sky above. Would a lower viewpoint of a different framing resolve that?</td>', 'Great B&W tones and great landscape. But it almost feels like two separate images, one the road with trees below and the other the trees, mountain and sky above. Would a lower viewpoint of a different framing resolve that?', '2020-11-03 08:58:42.000000', NULL, 1),
(7678638, 1255806, 4008, '<td valign="top">Why is the visitor in the frame? Why is the painting in the frame? Did you mean to make any connection between the two (other then the color) ? What is this image about ? I don''t get it.</td>', 'Why is the visitor in the frame? Why is the painting in the frame? Did you mean to make any connection between the two (other then the color) ? What is this image about ? I don''t get it.', '2020-11-03 09:02:26.000000', NULL, 1),
(7678639, 1255821, 4008, '<td valign="top">Seems overexposed, with the bird loosing color and detail.</td>', 'Seems overexposed, with the bird loosing color and detail.', '2020-11-03 09:04:40.000000', NULL, 1),
(7678641, 1255820, 4008, '<td valign="top">Beautiful still life. Nice texture.<br/> <br/>Did you add the pear on the right in post processing? The color separation line between background and table runs through the pear, as if it is slightly transparent. Also it shows much more shadow than the pears in the bowl.</td>', 'Beautiful still life. Nice texture. Did you add the pear on the right in post processing? The color separation line between background and table runs through the pear, as if it is slightly transparent. Also it shows much more shadow than the pears in the bowl.', '2020-11-03 09:11:57.000000', NULL, 1),
(7678642, 1255707, 4008, '<td valign="top">I like how the arms and the dress (?) create a circle composition around the head and draw the attention to the face.<br/> <br/>Not sure whether the legs add a lot to the image. I would try a tighter crop, maybe just below the waist. If you want to show the full body then I suggest to reflect a bit more light on the right foot in the left of the image, just enough to show the shape.</td>', 'I like how the arms and the dress (?) create a circle composition around the head and draw the attention to the face. Not sure whether the legs add a lot to the image. I would try a tighter crop, maybe just below the waist. If you want to show the full body then I suggest to reflect a bit more light on the right foot in the left of the image, just enough to show the shape.', '2020-11-03 09:16:56.000000', NULL, 1),
(7678644, 1255599, 4008, '<td valign="top">Nice details and tones. I wonder whether more contrast would also work. Also maybe cut of just a bit of the negative space at the bottom?</td>', 'Nice details and tones. I wonder whether more contrast would also work. Also maybe cut of just a bit of the negative space at the bottom?', '2020-11-03 09:24:23.000000', NULL, 1),
(7678645, 1255675, 4008, '<td valign="top">You have the circumstances for a great portrait here. I find the burning candle, the plastic container and the cell phone distracting in the image.</td>', 'You have the circumstances for a great portrait here. I find the burning candle, the plastic container and the cell phone distracting in the image.', '2020-11-03 09:26:12.000000', NULL, 1),
(7678647, 1255824, 4008, '<td valign="top">Fantastic landscape, great tones in forest, mountains and sky. Just the water feels strange, too smooth and strange dark patches.</td>', 'Fantastic landscape, great tones in forest, mountains and sky. Just the water feels strange, too smooth and strange dark patches.', '2020-11-03 09:29:53.000000', NULL, 1),
(7678648, 1255800, 4008, '<td valign="top">Great action shot, hanging in the air.</td>', 'Great action shot, hanging in the air.', '2020-11-03 09:30:38.000000', NULL, 1),
(7678649, 1255852, 4008, '<td valign="top">Fantastic sharp and intense portrait, great division of light/dark tones, good neutral expression, perfect. My choice for the blue this month.</td>', 'Fantastic sharp and intense portrait, great division of light/dark tones, good neutral expression, perfect. My choice for the blue this month.', '2020-11-03 09:31:36.000000', NULL, 1),
(7678650, 1255822, 4008, '<td valign="top">Fantastic detail and colors. One slight distraction is the blue line in the background on the left side. In my top 4.</td>', 'Fantastic detail and colors. One slight distraction is the blue line in the background on the left side. In my top 4.', '2020-11-03 09:32:06.000000', NULL, 1),
(7678651, 1255847, 4008, '<td valign="top">Great sharpness, lovely colors, perfect timing. In my top 4.</td>', 'Great sharpness, lovely colors, perfect timing. In my top 4.', '2020-11-03 09:32:16.000000', NULL, 1),
(7678652, 1254931, 4008, '<td valign="top">Nice composition and colors and fantastic detail, especially considering how fast they move. In my top 4.</td>', 'Nice composition and colors and fantastic detail, especially considering how fast they move. In my top 4.', '2020-11-03 09:32:23.000000', NULL, 1),
(7678653, 1255832, 4008, '<td valign="top">Great image. I would edit out the blue barrel.</td>', 'Great image. I would edit out the blue barrel.', '2020-11-03 09:33:26.000000', NULL, 1),
(7678654, 1255478, 4008, '<td valign="top">Impressive tree, great soft colors and atmosphere. Not sure whether this is the best composition with the path running through the right side of the image, but great image all the same.</td>', 'Impressive tree, great soft colors and atmosphere. Not sure whether this is the best composition with the path running through the right side of the image, but great image all the same.', '2020-11-03 09:34:14.000000', NULL, 1),
(7678655, 1255863, 4008, '<td valign="top">I like the structure, the tones, the large white space.</td>', 'I like the structure, the tones, the large white space.', '2020-11-03 09:35:46.000000', NULL, 1),
(7678656, 1255802, 4008, '<td valign="top">Very attractive. The lady is just in the right spot for the composition, with the lines of the waves framing her and then leading the eye to the sun.<br/> <br/>Could be for a holiday advertisement. Makes us all long for the possibility for free travel again.</td>', 'Very attractive. The lady is just in the right spot for the composition, with the lines of the waves framing her and then leading the eye to the sun. Could be for a holiday advertisement. Makes us all long for the possibility for free travel again.', '2020-11-03 09:38:42.000000', NULL, 1),
(7678657, 1255757, 4008, '<td valign="top">Intriguing image. Feel like a painting. I would de-emphasise or edit out the dark shadow under the column top-left.</td>', 'Intriguing image. Feel like a painting. I would de-emphasise or edit out the dark shadow under the column top-left.', '2020-11-03 09:42:08.000000', NULL, 1),
(7678658, 1255780, 4008, '<td valign="top">I don''t like the effect.</td>', 'I don''t like the effect.', '2020-11-03 09:42:49.000000', NULL, 1),
(7678659, 1255878, 4008, '<td valign="top">Just another sunset to me. Nothing special.</td>', 'Just another sunset to me. Nothing special.', '2020-11-03 09:43:38.000000', NULL, 1),
(7678722, 1255577, 113411, '<td valign="top">This is fabulous !!!!</td>', 'This is fabulous !!!!', '2020-11-04 06:13:32.000000', NULL, 1),
(7678723, 1255840, 113411, '<td valign="top">Incredible!</td>', 'Incredible!', '2020-11-04 06:14:04.000000', NULL, 1),
